{
  "appName": "Helpdesk",
  "appType": "customer support helpdesk",
  "summary": "A customer support helpdesk application for managing tickets, with features for users, agents, managers, and premium users with SLA tracking.",
  "entities": [
    {
      "name": "ticket",
      "fields": ["id", "subject", "description", "priority", "status", "createdAt", "updatedAt", "assignedAgentId", "customerId"]
    },
    {
      "name": "user",
      "fields": ["id", "name", "email", "role"]
    },
    {
      "name": "analytics",
      "fields": ["totalTickets", "openTickets", "closedTickets", "averageResponseTime", "slaViolations"]
    },
    {
      "name": "sla",
      "fields": ["id", "ticketId", "targetResponseTime", "targetResolutionTime", "startTime", "endTime", "violated"]
    }
  ],
  "roles": ["user", "agent", "manager", "premiumUser"],
  "features": ["ticketManagement", "userManagement", "analytics", "slaTracking", "roleBasedAccess"],
  "hasAuth": true,
  "hasPayments": false,
  "ambiguities": ["The exact criteria for 'premium' access and how it is granted are not specified."],
  "assumptions": [
    "Users will have accounts to submit tickets.",
    "Agents will be assigned tickets.",
    "Managers will have read-only access to analytics.",
    "Premium users are a subset of users who pay for SLA tracking.",
    "SLA tracking is a premium feature."
  ],
  "clarifyingQuestions": []
}
